package dev.exodus.supply.catalog;import com.google.gson.*;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import static org.junit.jupiter.api.Assertions.*;class TeleporterMaterialSupplyTest{@Test void threeSpecialOnlyDefinitionsHaveApprovedCostsAndLimits()throws Exception{check("energy",16,"minecraft:iron_ingot");check("optics",12,"minecraft:copper_ingot");check("processing",8,"minecraft:gold_ingot");}private void check(String name,int count,String item)throws Exception{String path="data/exodus/exodus_supply_drops/teleporter_"+name+"_materials.json";try(InputStream in=getClass().getClassLoader().getResourceAsStream(path)){assertNotNull(in,path);JsonObject json=JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject();assertEquals("special",json.getAsJsonArray("radio_types").get(0).getAsString());assertEquals(1,json.get("max_requests").getAsInt());assertEquals(count,json.getAsJsonObject("cost").get("count").getAsInt());assertEquals(item,json.getAsJsonObject("cost").get("item").getAsString());}}}
